SELECT id, document_id, seq, title, content, token_count, meta, created_at
FROM parent_chunks
WHERE id = #{id}

SELECT id, document_id, seq, title, content, token_count, meta, created_at
FROM parent_chunks
WHERE document_id = #{documentId}
ORDER BY seq ASC
LIMIT #{size} OFFSET #{offset}

